# English Language: error spotting and sentence improvement (fixed option order, lockedOrder).
SI = "Which of the following should replace the part in bold to make the sentence correct? If no replacement is needed, choose 'No improvement'."
ITEMS = [
    # ---------- Mock Test 1: error spotting ----------
    L(1, 1, "Error spotting", ERR + "\n\nEither the clerks (A) / or the cashier (B) / have to sign (C) / the cash register. (D) / No error (E)", LETTERS, 2,
      "With 'either ... or', the verb agrees with the nearer subject. 'The cashier' is singular, so the verb is 'has to sign'."),
    L(1, 1, "Error spotting", ERR + "\n\nThe manager asked me (A) / that why I was (B) / late for (C) / the meeting. (D) / No error (E)", LETTERS, 1,
      "A reported question is joined by the question word alone, without 'that': 'asked me why I was late'."),
    L(1, 2, "Error spotting", ERR + "\n\nThe luggages (A) / of the passengers (B) / was kept (C) / in the cloakroom. (D) / No error (E)", LETTERS, 0,
      "'Luggage' is uncountable and has no plural form, so 'the luggage ... was kept' is correct."),
    L(1, 2, "Error spotting", ERR + "\n\nThe doctor told him (A) / to avoid (B) / to eat (C) / fried food. (D) / No error (E)", LETTERS, 2,
      "'Avoid' is followed by the -ing form, not the infinitive: 'to avoid eating fried food'."),
    L(1, 2, "Error spotting", ERR + "\n\nThe loan officer, along with (A) / his two clerks, (B) / is visiting the village (C) / to meet the borrowers. (D) / No error (E)", LETTERS, 4,
      "The sentence is correct. A phrase added with 'along with' does not change the subject, 'the loan officer', which takes the singular 'is'."),
    L(1, 3, "Error spotting", ERR + "\n\nHe insisted on (A) / paying the bill (B) / although he could (C) / hardly afforded it. (D) / No error (E)", LETTERS, 3,
      "After the modal 'could', the verb takes its base form: 'could hardly afford it'."),
    L(1, 3, "Error spotting", ERR + "\n\nThe committee has (A) / submitted its report (B) / and the members (C) / are satisfied with it. (D) / No error (E)", LETTERS, 4,
      "The sentence is correct. 'The committee' acting as one body takes 'has' and 'its', while 'the members' is plural and takes 'are'."),
    # ---------- Mock Test 1: sentence improvement ----------
    L(1, 1, "Sentence improvement", SI + "\n\nThe meeting was postponed **due to the reason that** the chairman was ill.",
      ["because", "owing that", "due to that", "for reason that", "No improvement"], 0,
      "'Due to the reason that' is wordy; 'because' says the same thing correctly."),
    L(1, 1, "Sentence improvement", SI + "\n\nThe heavy rain **prevented us to go** out.",
      ["prevented us from going", "prevented us for going", "prevented that we go", "prevented us going to", "No improvement"], 0,
      "Prevent takes an object and from + -ing: prevented us from going out."),
    L(1, 2, "Sentence improvement", SI + "\n\n**Having finished the work,** the officer left for home.",
      ["Having finish the work,", "The work having finished,", "After finishing of the work,", "Finished the work,", "No improvement"], 4,
      "The sentence is correct: the participle phrase 'Having finished the work' refers to the subject, the officer."),
    L(1, 2, "Sentence improvement", SI + "\n\nHe did not know **where was the file** kept.",
      ["where had the file", "that where the file was", "where the file was", "where was kept the file", "No improvement"], 2,
      "In a reported question the subject comes before the verb: 'where the file was kept'."),
    L(1, 3, "Sentence improvement", SI + "\n\nThe officer **as well as his staff were** praised for the audit.",
      ["as well as his staff were being", "together with his staffs was", "as well as his staffs were", "as well as his staff was", "No improvement"], 3,
      "A phrase added with 'as well as' does not change the subject, 'the officer', so the verb is singular: 'was praised'. 'Staff' takes no -s here."),

    # ---------- Mock Test 2: error spotting ----------
    L(2, 1, "Error spotting", ERR + "\n\nMy uncle (A) / gave me an useful (B) / book on banking (C) / for my birthday. (D) / No error (E)", LETTERS, 1,
      "'Useful' begins with a 'yoo' sound, which is a consonant sound, so it takes 'a': 'a useful book'."),
    L(2, 2, "Error spotting", ERR + "\n\nThe children were (A) / so tired that they (B) / could not hardly walk (C) / back home. (D) / No error (E)", LETTERS, 2,
      "'Hardly' is already negative, so 'could not hardly walk' is a double negative. It should be 'could hardly walk back home'."),
    L(2, 2, "Error spotting", ERR + "\n\nTen kilometres (A) / are a long distance (B) / to walk (C) / every day. (D) / No error (E)", LETTERS, 1,
      "An amount of distance treated as one quantity takes a singular verb: 'Ten kilometres is a long distance'."),
    L(2, 1, "Error spotting", ERR + "\n\nThe scenery of (A) / the hill station (B) / was so beautiful (C) / that we stayed longer. (D) / No error (E)", LETTERS, 4,
      "The sentence is correct. 'Scenery' is uncountable and takes the singular 'was'."),
    L(2, 2, "Error spotting", ERR + "\n\nLet him and I (A) / finish the report (B) / before the manager (C) / returns. (D) / No error (E)", LETTERS, 0,
      "'Let' takes object pronouns: 'Let him and me finish the report'."),
    L(2, 2, "Error spotting", ERR + "\n\nI have seen (A) / that film (B) / last week (C) / with my cousins. (D) / No error (E)", LETTERS, 0,
      "A finished past time such as 'last week' needs the simple past: 'I saw that film last week'."),
    L(2, 3, "Error spotting", ERR + "\n\nShe asked me (A) / where I was going (B) / and why did I (C) / look so worried. (D) / No error (E)", LETTERS, 2,
      "In reported speech the question takes statement order with no 'did': 'and why I looked so worried'."),
    # ---------- Mock Test 2: sentence improvement ----------
    L(2, 1, "Sentence improvement", SI + "\n\nThe doctor advised him **to give up smoking**.",
      ["to give off smoking", "giving up to smoke", "to give up to smoke", "for giving up smoking", "No improvement"], 4,
      "The sentence is correct: 'advise someone to do something', and 'give up' is followed by the -ing form."),
    L(2, 1, "Sentence improvement", SI + "\n\n**Each of the clerks have** finished the training.",
      ["Each of the clerks has", "Each of the clerk has", "Every of the clerks have", "Each clerks have", "No improvement"], 0,
      "'Each' is singular and takes 'has', while 'of the' is followed by the plural 'clerks'."),
    L(2, 2, "Sentence improvement", SI + "\n\nSunita **married with** a doctor from Pune last year.",
      ["married to", "married", "got married with", "was married with", "No improvement"], 1,
      "Marry takes a direct object with no preposition: Sunita married a doctor. (She was married to a doctor is also correct, but it describes a state, not the event last year.)"),
    L(2, 2, "Sentence improvement", SI + "\n\nThe new manager is **more stricter than** the old one.",
      ["most strict than", "more strict then", "stricter than", "strictest than", "No improvement"], 2,
      "'Stricter' is already comparative, so 'more' is a double comparative. The correct form is 'stricter than'."),
    L(2, 3, "Sentence improvement", SI + "\n\nHe **has gone to Delhi yesterday** for a training course.",
      ["had gone to Delhi yesterday", "was gone to Delhi yesterday", "goes to Delhi yesterday", "went to Delhi yesterday", "No improvement"], 3,
      "'Yesterday' is a finished past time, so the simple past is needed: 'went to Delhi yesterday'."),

    # ---------- Drill only ----------
    L(0, 1, "Error spotting", ERR + "\n\nThe teacher, as well as (A) / the students, (B) / were present (C) / at the function. (D) / No error (E)", LETTERS, 2,
      "A phrase added with 'as well as' does not change the subject. 'The teacher' is singular, so the verb is 'was present'."),
    L(0, 2, "Error spotting", ERR + "\n\nScarcely had we (A) / sat down for dinner (B) / when the lights (C) / went out. (D) / No error (E)", LETTERS, 4,
      "The sentence is correct: 'scarcely' takes inverted word order and 'when'."),
    L(0, 1, "Sentence improvement", SI + "\n\nShe is **too much tired** to walk any further.",
      ["very much tired", "too tired", "so much tired", "too more tired", "No improvement"], 1,
      "Before an adjective, 'too' is used alone: 'too tired to walk'. 'Much' does not go with 'tired' here."),
]
